(function(root){'use strict';
const PREFIX='mt.handover.v1:',models={beam:'beam',transient:'transient',cycle:'ideal-cycle',pump:'pump-suction',refrigeration:'refrigeration-energy',heavyLift:'lift-cross-curves'},safe=q=>/^[A-Za-z0-9:._-]{1,120}$/.test(q),plain=v=>v&&typeof v==='object'&&!Array.isArray(v)&&Object.values(v).every(x=>typeof x==='string'&&!x.includes('$')||typeof x==='number'&&Number.isFinite(x));
function targets(q){const out=[];for(const r of q.references||[])if(r.kind==='model'&&models[r.id]&&plain(r.inputs)&&typeof r.output==='string')out.push({kind:'model',id:models[r.id],inputs:r.inputs,output:r.output,scale:r.answerScale||1,unit:q.unit});const p=q.params;if(p){if(q.chapter===3)out.push({kind:'model',id:'thermal-expansion',inputs:{E:200,alpha:p.alpha,length:p.length,area:1000,delta:p.delta,restraint:0},metric:'Free length change (mm)',unit:'mm',scale:1});const c={8:['buck-converter',{vin:p.supply,duty:p.duty},'V',1],11:['pump-time',{vol:p.volume,flow:p.flow},'h',60],14:['displacement',{volume:p.volume,density:p.density},'t',1]}[q.chapter];if(c)out.push({kind:'calculator',id:c[0],inputs:c[1],unit:q.unit,resultUnit:c[2],scale:c[3]});}return out;}
function begin(q,target){if(!safe(q.id)||!targets(q).some(t=>JSON.stringify(t)===JSON.stringify(target)))throw Error('Choose a verified exercise transfer.');const id=crypto.randomUUID(),returnUrl=new URL('../workspace.html',new URL('/students/',location.origin));returnUrl.hash='practice?chapter='+q.chapter+'&question='+encodeURIComponent(q.id);sessionStorage.setItem(PREFIX+id,JSON.stringify({version:1,id,qid:q.id,chapter:q.chapter,createdAt:Date.now(),target,returnUrl:returnUrl.pathname+returnUrl.hash}));return target.kind==='model'?'students/interactive.html?handover='+id+'#'+target.id:'students/?handover='+id+'#calculator/'+target.id;}
function read(id){if(!/^[a-f0-9-]{36}$/.test(id||''))throw Error('Invalid exercise transfer.');const value=JSON.parse(sessionStorage.getItem(PREFIX+id)||'null');if(value?.version!==1||value.id!==id||!safe(value.qid)||Date.now()-value.createdAt>86400000||!plain(value.target?.inputs)||!Number.isFinite(value.target.scale)||!/^\/workspace\.html#practice\?/.test(value.returnUrl))throw Error('Exercise transfer expired or is invalid.');return value;}
function returnValue(id,value,unit){const item=read(id);if(!Number.isFinite(value)||unit!==item.target.unit)throw Error('The result does not match the requested answer unit.');sessionStorage.setItem(PREFIX+id,JSON.stringify({...item,result:{value,unit,at:Date.now()}}));root.top.location.href=item.returnUrl+'&returned='+encodeURIComponent(id);}
function consume(id,qid){const item=read(id);if(item.qid!==qid||!item.result||!Number.isFinite(item.result.value))throw Error('No matching model answer was returned.');sessionStorage.removeItem(PREFIX+id);return item.result;}
root.MT_HANDOVER={targets,begin,read,returnValue,consume};
})(typeof window==='undefined'?globalThis:window);
